<?php
namespace App\Services;
use App\Models\{Guardian,Staff,Student};
class AudienceResolver{public function resolve(string $type,array $rules):array{$rows=[];if($type==='students'||$type==='guardians'){$q=Student::with(['guardian','guardians'])->when($rules['class_id']??null,fn($x,$id)=>$x->whereHas('currentEnrollment',fn($e)=>$e->where('class_id',$id)))->when($rules['section_id']??null,fn($x,$id)=>$x->whereHas('currentEnrollment',fn($e)=>$e->where('section_id',$id)))->when(isset($rules['status']),fn($x)=>$x->where('status',$rules['status']))->get();foreach($q as $s){$gs=$s->guardians->isNotEmpty()?$s->guardians:collect([$s->guardian])->filter();foreach($type==='students'?collect([$s]):$gs as $p)$rows[]=['type'=>$type==='students'?'student':'guardian','id'=>$p->id,'name'=>trim(($p->first_name??$p->father_name).' '.($p->last_name??'')),'phone'=>$type==='students'?($s->phone?:$s->guardian?->father_phone):($p->father_phone?:$p->mother_phone),'email'=>$type==='students'?$s->email:$p->guardian_email,'user_id'=>$p->user_id??null,'student'=>$s];}}else{$q=Staff::when($rules['department_id']??null,fn($x,$id)=>$x->where('department_id',$id))->where('is_active',true)->get();foreach($q as $p)$rows[]=['type'=>'staff','id'=>$p->id,'name'=>trim($p->first_name.' '.$p->last_name),'phone'=>$p->phone??null,'email'=>$p->email??null,'user_id'=>$p->user_id,'student'=>null];}return collect($rows)->unique(fn($x)=>$x['type'].':'.$x['id'])->values()->all();}}
